#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# Run from the repo root so the library's relative ENV_FILE (.env) and every
# path below resolve there, wherever the wizard was invoked from.
cd "$REPO_ROOT"

# ── Facts this wizard is built on ─────────────────────────────────────────
#
# The live Supabase project. Stages 2, 8 and 9 all refuse to act on the
# wrong one, in opposite directions: stage 2 must touch ONLY this, stages 8
# and 9 must NEVER touch it.
LIVE_SUPABASE_REF="jttycbhcziffiukpcwvd"

# The Manus-era project (ticket 31). Still running, in an organization the
# owner is not an admin of, so it cannot be paused. Rotating its keys is the
# whole of the practical remedy.
MANUS_SUPABASE_REF="mgsbipibzzwrvnseftar"

# The intermediate project, paused by hand 2026-09-28 and answering 401 again
# on 2026-10-03. Stage 9 asks the human to read its real state, because no
# probe from outside can tell paused from running: an unauthenticated 401
# only separates a real project from a nonexistent one.
INTERMEDIATE_SUPABASE_REF="geewhajddtzoisumbbek"

RENDER_HOST="https://spellcode-backend.onrender.com"
SWEEP_PATH="/api/scheduled/reconcile-payments"
MIGRATION="docs/supabase_payment_reconciliation_migration.sql"
ROLLBACK="docs/supabase_payment_reconciliation_rollback.sql"
WORKFLOW="reconcile-payments.yml"

# ── Resume state ──────────────────────────────────────────────────────────
#
# Both earlier wizards in this directory have NO resume state, and that is
# the single fault that cost the most: re-running finish-switch-wizard.sh to
# reach a later stage walks back through its stage 7, which cannot succeed
# and does not notice, so the run reads clean while the work stays open.
#
# This wizard resumes two ways, and prefers the first:
#
#   1. By PROBE, wherever reality can be read - the reconciliation_error
#      column either exists or it does not; the endpoint answers 503 or 401.
#      This repo's own conventions say prefer a probe to the prose, and a
#      probe cannot go stale the way a checkbox in a file can.
#   2. By STATE FILE, only for the stages nothing can probe - a key rotated
#      in a dashboard, a checkout a human watched succeed.
#
# The state file holds stage names and timestamps. No values, no secrets.
STATE_FILE="docs/domain-model-alignment/.operator-remainder.state"

mark_done() { printf '%s\t%s\n' "$1" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$STATE_FILE"; }
is_done()   { [[ -f "$STATE_FILE" ]] && grep -qE "^${1}\b" "$STATE_FILE"; }

# offer_skip NAME "what it was" returns success when the human wants to skip
# a stage the state file says is already done. It always OFFERS rather than
# skipping silently: a wizard that decides for you is how a stage gets
# quietly walked past.
offer_skip() {
  local name="$1" what="$2" when
  is_done "$name" || return 1
  when=$(grep -E "^${name}\b" "$STATE_FILE" | tail -n1 | cut -f2)
  note "This stage was recorded done at ${when}: $what"
  confirm "Skip it?" && return 0
  return 1
}

# require_env_ignored refuses to continue if .env is tracked, because stages
# 3 and 5 write into it. Carried over verbatim in intent from
# switch-wizard.sh, which ticket 20 asked for it in: a secret must not be
# written where a later `git add` would pick it up. `git check-ignore` only
# reads; this wizard runs no git command that changes the repository.
require_env_ignored() {
  if ! command -v git >/dev/null 2>&1; then
    warn "git not found, so the ignore check cannot run automatically."
    say "Check by hand that .env is listed in .gitignore."
    if ! confirm "Is .env gitignored?"; then
      warn "Stopping: .env must be gitignored before it holds a secret."
      exit 1
    fi
    return 0
  fi
  if (cd "$REPO_ROOT" && git check-ignore -q "$ENV_FILE") 2>/dev/null; then
    note "OK: $ENV_FILE is gitignored, so it is safe to write a secret into."
    return 0
  fi
  warn "$ENV_FILE is NOT gitignored. Refusing to write a secret into a file"
  warn "  git would track."
  say "Add '$ENV_FILE' to .gitignore, then re-run this wizard."
  exit 1
}

# secret_written NAME: success when set_secret actually wrote NAME. gh can be
# authenticated and the write still fail, so readiness is not the question.
secret_written() {
  local n
  for n in "${WRITTEN_SECRET[@]:-}"; do [[ "$n" == "$1" ]] && return 0; done
  return 1
}

# gh_secrets_url prints the Actions-secrets settings page for this repo,
# derived from origin rather than hardcoded, because the owner's name is
# capitalised differently in different places.
gh_secrets_url() {
  local slug
  slug="$(git -C "$REPO_ROOT" remote get-url origin 2>/dev/null \
    | sed -E 's#^.*github\.com[:/]##; s#\.git$##')"
  if [[ -n "$slug" ]]; then
    printf 'https://github.com/%s/settings/secrets/actions' "$slug"
  else
    printf 'https://github.com'
  fi
}

# ── Reading and probing ───────────────────────────────────────────────────

# read_env KEY prints KEY's value from .env.
read_env() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  line="${line#*=}"; line="${line%\"}"; line="${line#\"}"
  printf '%s' "$line"
}

# postgrest PATH runs a read-only PostgREST query with the service-role key.
# Read-only by construction: this wizard sends no method but GET here.
postgrest() {
  local url key
  url=$(read_env SUPABASE_URL || true)
  key=$(read_env SUPABASE_SERVICE_ROLE_KEY || true)
  [[ -n "$url" && -n "$key" ]] || return 1
  curl -fsS --max-time 30 -H "apikey: $key" -H "Authorization: Bearer $key" \
    "${url%/}/rest/v1/$1"
}

# sweep_code prints the HTTP status of an unauthenticated POST to the sweep
# endpoint. It carries no secret, so it can never start a run:
#
#   503  the endpoint is live and SCHEDULED_TASKS_SECRET is NOT set on Render
#   401  the endpoint is live and the secret IS set
#   200  something is very wrong - it should never authenticate an empty secret
#   404 / 000  the endpoint is not deployed, or the host is unreachable
#
# The 503 is returned BEFORE the secret is checked, in
# registerReconciliationEndpoint - "Scheduled tasks are not configured"
# precedes the "Invalid scheduled task secret" line. That ordering is what
# makes 503 and 401 distinguishable at all, and it is deliberately unlike
# switch-wizard.sh stage 8, where an empty webhook-events array could not
# tell "never set" from "set, nothing fired yet".
#
# Cited by symbol and message rather than by line: the line numbers in this
# effort's own docs went stale inside the effort, when ticket 34 moved
# initializeCheckout by ~34 lines.
sweep_code() {
  # curl's own -w prints 000 when it cannot reach the host, so appending a
  # second 000 on failure produced "000000", which no caller matches. Only
  # an absent curl prints nothing at all, and that is the one case that
  # needs a substitute.
  local code
  code="$(curl -s -o /dev/null -w '%{http_code}' --max-time 120 \
    -X POST "${RENDER_HOST}${SWEEP_PATH}" 2>/dev/null)"
  printf '%s' "${code:-000}"
}

# column_exists TABLE COLUMN: success when PostgREST can select the column.
# A missing column answers 42703 and curl -f makes that a failure.
column_exists() { postgrest "${1}?select=${2}&limit=1" >/dev/null 2>&1; }

# copy_to_clipboard VALUE puts a value on the clipboard where possible, so a
# secret gets into a dashboard without being printed into terminal scrollback.
copy_to_clipboard() {
  if   command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe && return 0
  elif command -v clip     >/dev/null 2>&1; then printf '%s' "$1" | clip     && return 0
  elif command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy   && return 0
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard && return 0
  fi
  return 1
}

banner "SpellCode: the operator remainder"

# -- 1 ---------------------------------------------------------------------
stage "Pre-flight"
say "Every ticket on the domain-model-alignment effort is closed in code."
say "What is left is operator work, and this is it: tickets 35, 34, 31, 32."
printf '\n'
warn "Do NOT run switch-wizard.sh or finish-switch-wizard.sh again."
note "  Neither has resume state. switch-wizard.sh walks from stage 1 and"
note "  would roll the Paystack keys and rebuild the database; and re-running"
note "  finish-switch-wizard.sh walks back through its stage 7, which cannot"
note "  succeed. This wizard resumes, and touches neither of their stages."
printf '\n'

if [[ ! -f "$ENV_FILE" ]]; then
  warn "No $ENV_FILE here. The verification reads SUPABASE_URL and"
  note "  SUPABASE_SERVICE_ROLE_KEY from it; without them you check by eye."
  confirm "Continue anyway?" || exit 1
else
  note "OK: $ENV_FILE found."
fi

# Before any stage can reach a write_env, not at the stage that writes: a
# refusal is worth hitting in pre-flight rather than six stages in.
require_env_ignored

if ! command -v curl >/dev/null 2>&1; then
  warn "curl not found. The probes below cannot run, and they will read as"
  note "  failures rather than as unknowns - treat every one of them as"
  note "  UNKNOWN, not as a negative result, and verify by eye instead."
fi
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  note "OK: gh is authenticated, so stages 3, 5 and 6 can act."
else
  warn "gh is not ready. Stages 3 and 5 will tell you the command to run by"
  note "  hand, and stage 6 cannot force a workflow run."
fi
printf '\n'

say "Reading the current state rather than assuming it:"
printf '\n'
PREFLIGHT_CODE=$(sweep_code)
case "$PREFLIGHT_CODE" in
  503) note "  sweep endpoint : 503 - deployed, secret NOT set on Render" ;;
  401) note "  sweep endpoint : 401 - deployed, secret IS set on Render" ;;
  000) warn "  sweep endpoint : unreachable. Render may be asleep; it can take" ;
       note "                   over 45 seconds to wake. Try again in a minute." ;;
  *)   warn "  sweep endpoint : $PREFLIGHT_CODE - unexpected. Expected 503 or 401." ;;
esac

if column_exists payment_transactions reconciliation_error; then
  note "  migration      : reconciliation_error present - already run"
else
  note "  migration      : reconciliation_error absent, or .env could not read"
fi
printf '\n'
pause "Ready?"

# -- 2 ---------------------------------------------------------------------
stage "Ticket 35: run the reconciliation migration"
say "This adds payment_transactions.reconciliation_error, which is how a"
say "payment the sweep cannot resolve becomes visible to a human."
printf '\n'

if column_exists payment_transactions reconciliation_error; then
  note "Probed: the column already exists. Nothing to do."
  note "This is the probe deciding, not a checkbox - it cannot be stale."
  mark_done migration
  pause "Continue."
elif offer_skip migration "the migration was run"; then
  note "Skipped."
else
  say "An unrun migration is survivable here, and that is deliberate."
  note "  Ticket 35's review moved the flag-clearing write out of the shared"
  note "  settlement path precisely so that a deploy running ahead of this"
  note "  migration costs only the sweep. Before that change, one unrun"
  note "  migration would have stopped every payment in the system from"
  note "  granting anything. So this is safe to run late - just not never."
  printf '\n'
  say "The file to paste, in full:"
  note "  $MIGRATION"
  say "If it needs undoing:"
  note "  $ROLLBACK"
  printf '\n'
  open_url "https://supabase.com/dashboard/project/${LIVE_SUPABASE_REF}/sql/new"
  step "Confirm the project ref in the URL is ${LIVE_SUPABASE_REF} - the LIVE one."
  step "Paste the whole of $MIGRATION into the SQL editor."
  step "Run it."
  printf '\n'
  warn "This writes schema to the live production database."
  if confirm "Have you run it?"; then
    printf '\n'
    if column_exists payment_transactions reconciliation_error; then
      printf '  %s✓ verified%s the column now exists\n' "$GREEN" "$RESET"
      mark_done migration
    else
      warn "The column still does not read back. Either the migration did not"
      note "  apply, or .env cannot reach the project. Not recording this as done."
      SKIPPED+=("ticket 35: run $MIGRATION and verify reconciliation_error exists")
    fi
  else
    SKIPPED+=("ticket 35: run $MIGRATION against $LIVE_SUPABASE_REF")
    warn "Noted as outstanding. The sweep cannot flag anything without it."
  fi
fi
printf '\n'
pause "Continue."

# -- 3 ---------------------------------------------------------------------
stage "Ticket 35: the scheduled-tasks secret"
say "One value, needed in two places that are easy to confuse:"
printf '\n'
note "  Render's environment    - the endpoint authenticates the caller with it"
note "  GitHub Actions secrets  - the workflow sends it as a request header"
printf '\n'
say "Set it in only one and the schedule runs every ten minutes and is"
say "refused every time. This stage does GitHub; stage 4 does Render."
printf '\n'

EXISTING_SECRET=$(read_env SCHEDULED_TASKS_SECRET || true)
if [[ -n "$EXISTING_SECRET" ]]; then
  note "$ENV_FILE already holds SCHEDULED_TASKS_SECRET. Reusing it keeps"
  note "  Render and GitHub in agreement; generating a new one means redoing"
  note "  stage 4 as well."
  if confirm "Generate a NEW secret instead, replacing it everywhere?"; then
    EXISTING_SECRET=""
  fi
fi

if [[ -z "$EXISTING_SECRET" ]]; then
  if   command -v openssl >/dev/null 2>&1; then
    EXISTING_SECRET=$(openssl rand -hex 32)
  elif [[ -r /dev/urandom ]]; then
    EXISTING_SECRET=$(head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n')
  else
    warn "No openssl and no /dev/urandom. Paste a long random value yourself."
    ask_secret SCHEDULED_TASKS_SECRET "Paste a secret (32+ random characters):"
    EXISTING_SECRET="$SCHEDULED_TASKS_SECRET"
  fi
fi

# An empty value here would be written to .env and GitHub, and the endpoint
# treats an unset secret as "refuse everyone" - so the failure would look
# like stage 4 never having been done, three stages later.
if [[ -z "$EXISTING_SECRET" ]]; then
  warn "No secret was captured, so there is nothing to write."
  note "  Re-run this stage with a value; an empty secret makes the endpoint"
  note "  refuse every scheduled run, which reads exactly like a missing one."
  SKIPPED+=("ticket 35: SCHEDULED_TASKS_SECRET was never generated")
  pause "Continue."
else
  note "A ${#EXISTING_SECRET}-character secret is ready."
  write_env SCHEDULED_TASKS_SECRET "$EXISTING_SECRET"
  set_secret SCHEDULED_TASKS_SECRET "$EXISTING_SECRET"
  printf '\n'
  note "The value is not printed here, so it stays out of terminal scrollback."
  note "Stage 4 puts it on your clipboard for the Render dashboard."
  printf '\n'
  # set_secret records a success in WRITTEN_SECRET, so ask it whether the
  # write landed rather than re-testing gh: gh can be authenticated and the
  # write still fail, and this stage is one of ticket 35's blocking items.
  if ! secret_written SCHEDULED_TASKS_SECRET; then
    warn "The GitHub secret was not written, so the workflow has no secret"
    warn "  yet and every scheduled run will be refused."
    printf '\n'
    open_url "$(gh_secrets_url)"
    step "New repository secret."
    step "Name: SCHEDULED_TASKS_SECRET"
    step "Secret: the same value stage 4 will put on your clipboard, or read"
    step "  it with: grep '^SCHEDULED_TASKS_SECRET=' $ENV_FILE"
    step "Add secret."
    printf '\n'
    confirm "Added it in the browser?" || \
      SKIPPED+=("ticket 35: SCHEDULED_TASKS_SECRET in GitHub Actions secrets")
    printf '\n'
  fi
  pause "Continue."
fi

# -- 4 ---------------------------------------------------------------------
stage "Ticket 35: paste the same secret into Render"
say "The value must match what stage 3 wrote. Anything else and the endpoint"
say "refuses the schedule, which looks exactly like the secret being absent."
printf '\n'

if [[ "$(sweep_code)" == "401" ]] && ! confirm "Render already has a secret set (probed 401). Replace it?"; then
  note "Leaving Render's value alone."
  mark_done render_secret
else
  if [[ -n "$EXISTING_SECRET" ]] && copy_to_clipboard "$EXISTING_SECRET"; then
    printf '  %s✓ copied%s the secret to your clipboard\n' "$GREEN" "$RESET"
  else
    warn "Could not reach a clipboard. Read the value from $ENV_FILE:"
    note "  grep '^SCHEDULED_TASKS_SECRET=' $ENV_FILE"
  fi
  printf '\n'
  open_url "https://dashboard.render.com"
  step "Open the spellcode-backend service."
  step "Environment, then Add Environment Variable."
  step "Key: SCHEDULED_TASKS_SECRET   Value: paste from the clipboard."
  step "Save. Render will redeploy - that restarts production briefly."
  printf '\n'
  warn "Saving here restarts the live backend."
  if confirm "Saved, and the redeploy has finished?"; then
    printf '\n'
    say "Checking that the endpoint changed its answer. Six probes, 20s apart"
    say "between them, so this stage is bounded at roughly four minutes -"
    say "a cold Render start can exceed 45s, but not four minutes."
    FLIPPED=""
    for _attempt in 1 2 3 4 5 6; do
      CODE=$(sweep_code)
      note "  probe $_attempt of 6: $CODE"
      if [[ "$CODE" == "401" ]]; then FLIPPED="yes"; break; fi
      if [[ "$_attempt" != "6" ]]; then
        note "  not yet - waiting 20s"
        sleep 20
      fi
    done
    if [[ -n "$FLIPPED" ]]; then
      printf '  %s✓ verified%s 503 became 401: Render holds the secret\n' "$GREEN" "$RESET"
      mark_done render_secret
    else
      warn "Still not 401. The variable may not have saved, or the redeploy"
      note "  is not finished. Re-run this wizard later; stage 1 will tell you."
      SKIPPED+=("ticket 35: SCHEDULED_TASKS_SECRET on Render (endpoint still refuses)")
    fi
  else
    SKIPPED+=("ticket 35: SCHEDULED_TASKS_SECRET in Render's environment")
    warn "Noted as outstanding."
  fi
fi
printf '\n'
pause "Continue."

# -- 5 ---------------------------------------------------------------------
stage "Ticket 35: APP_URL for the workflow"
say "The workflow POSTs to \$APP_URL$SWEEP_PATH."
printf '\n'
note "It goes in as a SECRET, not a variable, even though the value is public:"
note "  reconcile-payments.yml reads secrets.APP_URL, and a repository"
note "  variable of the same name would resolve to empty. The workflow then"
note "  fails loudly rather than sweeping nothing, which is the right"
note "  behaviour but a confusing thing to debug."
printf '\n'
say "Point it at Render directly rather than through the Vercel proxy:"
note "  fewer hops, and the proxy adds nothing for a server-to-server call."
printf '\n'

APP_URL_VALUE=$(read_env RENDER_URL || true)
APP_URL_VALUE="${APP_URL_VALUE:-$RENDER_HOST}"
ask APP_URL "APP_URL [$APP_URL_VALUE]:"
APP_URL="${APP_URL:-$APP_URL_VALUE}"
write_env APP_URL "$APP_URL"
set_secret APP_URL "$APP_URL"
printf '\n'
if ! secret_written APP_URL; then
  warn "APP_URL did not reach GitHub. The workflow fails loudly without it,"
  warn "  so ticket 35 stays open until this is set."
  printf '\n'
  open_url "$(gh_secrets_url)"
  step "New repository secret."
  step "Name: APP_URL"
  step "Secret: $APP_URL"
  step "Add secret."
  printf '\n'
  confirm "Added it in the browser?" || \
    SKIPPED+=("ticket 35: APP_URL in GitHub Actions secrets")
  printf '\n'
fi
pause "Continue."

# -- 6 ---------------------------------------------------------------------
stage "Ticket 35: prove the sweep actually runs"
say "switch-wizard.sh stage 8 was marked done on the strength of the endpoint"
say "answering correctly, which was never the same claim as Paystack"
say "delivering. That cost a real payment. So: force a run and read its"
say "conclusion from GitHub - this stage does not ask you whether it worked."
printf '\n'
note "A green run is real evidence here, not a formality: the workflow runs"
note "  curl --fail-with-body under set -euo pipefail, so anything but a 2xx"
note "  from the endpoint fails the step. Green means the secret matched and"
note "  the sweep returned its summary."
printf '\n'

CODE=$(sweep_code)
if [[ "$CODE" != "401" ]]; then
  warn "The endpoint answers $CODE, not 401. A forced run will fail."
  note "  Finish stage 4 first."
  SKIPPED+=("ticket 35: prove the sweep runs (endpoint answered $CODE)")
elif ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "gh is not ready, so the run cannot be forced from here."
  note "  Do it in the browser: Actions, Reconcile payments, Run workflow."
  note "  workflow_dispatch exists on that workflow for exactly this."
  SKIPPED+=("ticket 35: force one run of $WORKFLOW and read its log")
else
  say "The workflow has workflow_dispatch so a human can force a run rather"
  say "than waiting up to ten minutes for the clock."
  printf '\n'
  if confirm "Force one run now?"; then
    if gh workflow run "$WORKFLOW" >/dev/null 2>&1; then
      note "Dispatched. Polling for the conclusion, up to about two minutes."
      CONCLUSION=""
      for _attempt in 1 2 3 4 5 6 7 8; do
        sleep 15
        RUN_STATE="$(gh run list --workflow "$WORKFLOW" --limit 1 \
          --json status,conclusion \
          --jq '.[0] | "\(.status) \(.conclusion)"' 2>/dev/null || printf '')"
        note "  attempt $_attempt of 8: ${RUN_STATE:-could not read the run}"
        case "$RUN_STATE" in
          completed*) CONCLUSION="${RUN_STATE#completed }"; break ;;
        esac
      done
      printf '\n'
      case "$CONCLUSION" in
        success)
          mark_done sweep_proved
          printf '  %s✓ the safety net is live%s - GitHub reports success\n' "$GREEN" "$RESET"
          say "The run printed the sweep's own JSON summary, and that output is"
          say "the only record of what it did once the logs age out:"
          note "  gh run view --log --workflow $WORKFLOW"
          ;;
        "")
          warn "The run did not finish in time, or its state could not be read."
          note "  This is NOT a failure and NOT a success. Read it yourself:"
          note "  gh run view --log --workflow $WORKFLOW"
          SKIPPED+=("ticket 35: prove the sweep runs (the forced run's conclusion was never read)")
          ;;
        *)
          warn "GitHub reports the run concluded: $CONCLUSION"
          note "  curl --fail-with-body means the endpoint answered non-2xx, so"
          note "  the secret on Render and the secret in GitHub likely differ."
          note "  The body is in the log: gh run view --log --workflow $WORKFLOW"
          SKIPPED+=("ticket 35: the forced workflow run concluded $CONCLUSION - read its log")
          ;;
      esac
    else
      warn "gh could not dispatch the workflow."
      SKIPPED+=("ticket 35: force one run of $WORKFLOW")
    fi
  else
    SKIPPED+=("ticket 35: force one run of $WORKFLOW and read its log")
  fi
fi
printf '\n'
pause "Continue."

# -- 7 ---------------------------------------------------------------------
stage "Ticket 34: the test-mode checkout that is still owed"
say "Ticket 34 rewrote initializeCheckout - the only function in this effort"
say "with production evidence behind it - and left its live-checkout"
say "acceptance box unticked. Its tests cover the guard; no browser has run it."
printf '\n'

if offer_skip checkout34 "a post-34 test checkout was completed"; then
  note "Skipped."
else
  warn "You need a THIRD test Learner, and this is the trap."
  note "  Ticket 34's new guard refuses a checkout when the Learner already"
  note "  holds a subscription in (active, past_due). The stage 10 account"
  note "  5499b299 has an ACTIVE Full Access subscription from 2026-09-27, so"
  note "  it will be refused - correctly. Signing in as it and seeing the"
  note "  refusal proves the guard, not the checkout. Use a new account."
  printf '\n'
  say "Wake Render first. A cold start exceeds 45 seconds and Paystack's"
  say "webhook timeout is 30, so a sleeping instance loses the delivery."
  open_url "$RENDER_HOST/api/mobile/config"
  pause "Press Enter once that returned JSON."

  PROD_ORIGIN=$(read_env VERCEL_ORIGIN || true)
  PROD_ORIGIN="${PROD_ORIGIN:-https://spellcode-by-aceify-two.vercel.app}"
  printf '\n'
  open_url "$PROD_ORIGIN/auth"
  step "Sign up as a NEW test Learner and confirm the email."
  step "Then go to Access and start a Full Access one-time checkout."
  printf '\n'
  say "Pay with a Paystack test card. Do not guess the number - the current"
  say "test cards are listed here:"
  open_url "https://paystack.com/docs/payments/test-payments/"
  printf '\n'
  warn "Confirm you are on the right Paystack business before reading any"
  note "  dashboard: the correct one is whichever lists the transaction"
  note "  spellcode-963cdeab-a97c-40e4-8b2f-16a20889c376. Dashboard URLs"
  note "  carry no business identifier, so no link can target one (ticket 30)."
  printf '\n'
  if confirm "Did the checkout complete and Full Access appear?"; then
    printf '\n'
    say "Reading the database rather than trusting the page:"
    postgrest "payment_transactions?select=reference,status,created_at&order=created_at.desc&limit=3" || warn "could not read payment_transactions"
    printf '\n'
    postgrest "subscriptions?select=status,installments_paid,total_installments,created_at&order=created_at.desc&limit=3" || warn "could not read subscriptions"
    printf '\n'
    say "Expect the newest payment at status success, and a subscription at"
    say "active. Under ticket 34 the subscription is written at VERIFIED"
    say "payment, not at checkout - so there should be no pending row at all."
    printf '\n'
    if confirm "Does that match?"; then
      mark_done checkout34
      printf '  %s✓ ticket 34 has its browser verification%s\n' "$GREEN" "$RESET"
    else
      SKIPPED+=("ticket 34: the post-34 checkout did not settle as expected - investigate")
    fi
  else
    SKIPPED+=("ticket 34: a test-mode checkout after ticket 34 landed")
  fi
  printf '\n'
  warn "This grants Full Access on a test card, in production."
  note "  Exclude it from any revenue figure by user_id, by hand:"
  note "  payment_transactions has no mode column, so nothing distinguishes"
  note "  it from a real purchase and adminLearnerBilling will count it."
fi
printf '\n'
pause "Continue."

# -- 8 ---------------------------------------------------------------------
