if offer_skip rotate31 "the Manus project's keys were rotated"; then
  note "Skipped."
elif [[ "$MANUS_SUPABASE_REF" == "$LIVE_SUPABASE_REF" ]]; then
  warn "Refusing to act: the Manus ref matches the live ref. Someone has"
